import http from "node:http";
import https from "node:https";
import net from "node:net";
import process from "node:process";

const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const CLOSED_PORT = 65_534;

// WebTransport's internal datagram receiver currently starts an unobserved
// async task. A deliberately unreachable QUIC peer makes that implementation
// task reject after its idle timeout; the capability decision was synchronous
// in the constructor, and the public ready/closed promises are observed below.
addEventListener("unhandledrejection", (event) => {
  if (event.reason?.message === "timed out") event.preventDefault();
});

async function bounded(promise, cleanup = () => {}) {
  try {
    return await Promise.race([promise, delay(1_000)]);
  } finally {
    cleanup();
  }
}

async function fetchProbe() {
  await fetch(`http://127.0.0.1:${CLOSED_PORT}/`, {
    signal: AbortSignal.timeout(1_000),
  });
}

function customUnixFetchProbe(socketPath) {
  const client = Deno.createHttpClient({
    proxy: { transport: "unix", path: socketPath },
  });
  client.close();
}

function customVsockFetchProbe() {
  const client = Deno.createHttpClient({
    proxy: { transport: "vsock", cid: 2, port: 1 },
  });
  client.close();
}

async function nodeRequestProbe(client, options) {
  let req;
  await bounded(
    new Promise((resolve, reject) => {
      req = client.get(options, (response) => {
        response.resume();
        resolve();
      });
      req.once("error", reject);
    }),
    () => req?.destroy(),
  );
}

const nodeHttpProbe = () =>
  nodeRequestProbe(http, `http://127.0.0.1:${CLOSED_PORT}/`);
const nodeHttpDefaultPortProbe = () =>
  nodeRequestProbe(http, "http://127.0.0.1/");
const nodeHttpsProbe = () =>
  nodeRequestProbe(https, `https://127.0.0.1:${CLOSED_PORT}/`);
const nodeHttpUnixProbe = (socketPath) =>
  nodeRequestProbe(http, { socketPath, path: "/" });

async function websocketProbe() {
  let socket;
  await bounded(
    new Promise((resolve, reject) => {
      socket = new WebSocket(`ws://127.0.0.1:${CLOSED_PORT}/`);
      socket.onopen = resolve;
      socket.onerror = () => resolve();
    }),
    () => socket?.close(),
  );
}

async function denoTcpConnectProbe() {
  const conn = await Deno.connect({ hostname: "127.0.0.1", port: CLOSED_PORT });
  conn.close();
}

async function nodeTcpConnectProbe() {
  let socket;
  await bounded(
    new Promise((resolve, reject) => {
      socket = net.createConnection({ host: "127.0.0.1", port: CLOSED_PORT });
      socket.once("connect", resolve);
      socket.once("error", reject);
    }),
    () => socket?.destroy(),
  );
}

async function nodeUnixConnectProbe(socketPath) {
  let socket;
  await bounded(
    new Promise((resolve, reject) => {
      socket = net.createConnection(socketPath);
      socket.once("connect", resolve);
      socket.once("error", reject);
    }),
    () => socket?.destroy(),
  );
}

async function denoUnixConnectProbe(socketPath) {
  const conn = await Deno.connect({ transport: "unix", path: socketPath });
  conn.close();
}

async function denoVsockConnectProbe() {
  const conn = await Deno.connect({ transport: "vsock", cid: 2, port: 1 });
  conn.close();
}

async function quicConnectProbe() {
  const conn = await Deno.connectQuic({
    hostname: "127.0.0.1",
    port: CLOSED_PORT,
    maxIdleTimeout: 500,
  });
  conn.close();
}

async function webTransportProbe() {
  const transport = new WebTransport(`https://127.0.0.1:${CLOSED_PORT}/`, {
    congestionControl: "low-latency",
  });
  transport.closed.catch(() => {});
  await bounded(transport.ready, () => {
    try {
      transport.close();
    } catch {
      // A not-yet-connected transport cannot be closed; its QUIC idle timeout
      // is bounded above.
    }
  });
}

function denoTcpListenProbe() {
  const listener = Deno.listen({ hostname: "127.0.0.1", port: 0 });
  listener.close();
}

async function nodeTcpListenProbe() {
  await nodeListenProbe({ host: "127.0.0.1", port: 0 });
}

async function nodeListenProbe(options) {
  const server = net.createServer();
  let onUncaught;
  await bounded(
    new Promise((resolve, reject) => {
      onUncaught = reject;
      process.once("uncaughtException", onUncaught);
      server.once("error", reject);
      server.listen(options, resolve);
    }),
    () => {
      process.removeListener("uncaughtException", onUncaught);
      try {
        server.close();
      } catch {
        // A denied listen never starts the server.
      }
    },
  );
}

async function nodeUnixListenProbe(socketPath) {
  try {
    Deno.removeSync(socketPath);
  } catch {
    // Expected when the path does not exist.
  }
  try {
    await nodeListenProbe(socketPath);
  } finally {
    try {
      Deno.removeSync(socketPath);
    } catch {
      // A closed or denied Node pipe may already have removed the path.
    }
  }
}

function denoUnixListenProbe(socketPath) {
  try {
    Deno.removeSync(socketPath);
  } catch {
    // Expected when the path does not exist.
  }
  const listener = Deno.listen({ transport: "unix", path: socketPath });
  listener.close();
  Deno.removeSync(socketPath);
}

function denoVsockListenProbe() {
  const listener = Deno.listen({
    transport: "vsock",
    cid: 0xffff_ffff,
    port: 0,
  });
  listener.close();
}

function quicListenProbe() {
  const endpoint = new Deno.QuicEndpoint({ hostname: "127.0.0.1", port: 0 });
  endpoint.close();
}

const PROBES = [
  ["deno-fetch", "fetch", fetchProbe],
  ["custom-unix-fetch", "fetch", customUnixFetchProbe],
  ["custom-vsock-fetch", "fetch", customVsockFetchProbe],
  ["node-http-fetch", "fetch", nodeHttpProbe],
  ["node-http-default-port-fetch", "fetch", nodeHttpDefaultPortProbe],
  ["node-https-fetch", "fetch", nodeHttpsProbe],
  ["node-http-unix-fetch", "fetch", nodeHttpUnixProbe],
  ["websocket-connect", "connect", websocketProbe],
  ["deno-tcp-connect", "connect", denoTcpConnectProbe],
  ["node-tcp-connect", "connect", nodeTcpConnectProbe],
  ["node-unix-connect", "connect", nodeUnixConnectProbe],
  ["deno-unix-connect", "connect", denoUnixConnectProbe],
  ["deno-vsock-connect", "connect", denoVsockConnectProbe],
  ["quic-connect", "connect", quicConnectProbe],
  ["webtransport-connect", "connect", webTransportProbe],
  ["deno-tcp-listen", "listen", denoTcpListenProbe],
  ["node-tcp-listen", "listen", nodeTcpListenProbe],
  ["node-unix-listen", "listen", nodeUnixListenProbe],
  ["deno-unix-listen", "listen", denoUnixListenProbe],
  ["deno-vsock-listen", "listen", denoVsockListenProbe],
  ["quic-listen", "listen", quicListenProbe],
];

// @ref LLP 0019#protected-metadata-endpoints [constrained-by]
// The /1.1 profile has no authenticated proxy final-peer claim, so custom
// proxy transports stay closed even when the package holds fetch authority.
const PROFILE_CLOSED_PROBES = new Set([
  "custom-unix-fetch",
  "custom-vsock-fetch",
]);

// @ref llp/0010-the-capability-surface.spec.md#network [verifies] -- Each
// protocol surface selects one semantic action; grants for the other two must
// fail before the transport is touched.
export async function runNetworkActionMatrix(grantedAction, socketPath, only) {
  for (const [name, action, probe] of PROBES) {
    if (only && name !== only) continue;
    let denied = false;
    let observedError;
    try {
      await probe(socketPath);
    } catch (error) {
      observedError = error;
      denied = error?.name === "NotCapable" ||
        error?.cause?.name === "NotCapable";
    }
    const actual = denied ? "denied" : "allowed";
    const expected = PROFILE_CLOSED_PROBES.has(name)
      ? "denied"
      : action === grantedAction
      ? "allowed"
      : "denied";
    if (actual !== expected) {
      throw new Error(
        `${name}: ${grantedAction} grant expected ${expected}, got ${actual}; error=${observedError?.name}:${observedError?.message}; cause=${observedError?.cause?.name}:${observedError?.cause?.message}`,
      );
    }
    console.log(`${grantedAction} ${name} ${actual}`);
  }
  if (!only) console.log(`NETWORK_ACTION_MATRIX ${grantedAction} PASS`);
}
